questionvariables.text:
plist: [["AG","ABCD","GAC",["GAD","GAB","GAC","AGC"],10,8,7],["AG","ABFE","GAF",["GAB","GAE","GAF","AGF"],11,4,9],["AG","ADHE","GAH",["AGH","GAD","GAE","GAH"],15,17,4],["BH","ABCD","HBD",["HBA","HBC","BHD","HBD"],19,7,13],["CE","EFGH","CEG",["CEH","CEG","ECG","CEF"],9,7,15],["DF","BCGF","DFC",["DFG","FDC","DFC","DFB"],6,13,5],["EC","ABCD","ECA",["CEA","ECD","ECA","ECB"],7,11,12],["HB","BCGF","HBG",["HBF","HBG","HBC","BHG"],18,12,7],["AF","BCGF","AFB",["AFE","AFG","FAB","AFB"],5,11,12],["FD","ABCD","FDB",["DFB","FDA","FDB","FDC"],9,16,11]];
EDG: ["GAB","GAB","GAD","HBA","CEF","DFB","ECB","HBC","AFG","FDA"];
/* Design: angle between a line and a face of a cuboid. st: the end of the line in the plane; tp: the other end; ft: where the perpendicular from tp lands. Options: the answer, an angle with an edge of the plane, the angle at tp (complement), the angle with another line. Source: adapted from SMP GCSE Higher 2, Chapter 34, B10. */
ix: 1+rand(10); PP: plist[ix];
lin: PP[1]; pl: PP[2]; nm: PP[3]; OP: PP[4]; ll: PP[5]; ww: PP[6]; hh: PP[7];
LS: "ABCDEFGH"; LT: [[0,0,0],[ll,0,0],[ll,ww,0],[0,ww,0],[0,0,hh],[ll,0,hh],[ll,ww,hh],[0,ww,hh]];
pt(c) := LT[ssearch(c, LS)];
vv(s) := pt(charat(s,2)) - pt(charat(s,1));
sq(s) := vv(s) . vv(s);
dst(s) := float(sqrt(sq(s)));
angd(s) := block([u,w], u: pt(charat(s,1))-pt(charat(s,2)), w: pt(charat(s,3))-pt(charat(s,2)), float(acos((u . w)/sqrt((u . u)*(w . w)))*180/%pi));
r1(v) := float(floor(10*v+1/2)/10); r2(v) := float(floor(100*v+1/2)/100);
d1(v) := dispdp(r1(v),1); d2(v) := dispdp(r2(v),2); d4(v) := dispdp(float(floor(10000*v+1/2)/10000),4);
NA: -999; NB: -888; NC: -777;
nf(v) := if integerp(v) then v else float(v);
st: charat(nm,2); ft: charat(nm,3); tp: charat(nm,1);
proj: sconcat(st,ft); perp: sconcat(tp,ft); qP: sq(proj); qH: sq(perp);
th: angd(nm); ed: EDG[ix]; edv: angd(ed); edl: sconcat(st, charat(ed,3)); cp: 90-th;
thr: r1(th); tha: th+0.2; thg: th+1.0; thrad: float(th*%pi/180);
opts: makelist([o, is(o = nm), o], o, OP);
oc: first(sublist(OP, lambda([o], is(charat(o,2) # st))));
oo: first(sublist(OP, lambda([o], is(o # nm and o # ed and charat(o,2) = st))));
